// In-memory notes store
const notes = new Map();
let counter = 0;

function assertString(value, name) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new Error(`${name} is required and must be a non-empty string`);
  }
}

export async function listTools() {
  return [
    {
      name: 'note_create',
      description: 'Create a new note with a title and body.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'The title of the note.' },
          body: { type: 'string', description: 'The body of the note.' },
        },
        required: ['title', 'body'],
      },
    },
    {
      name: 'note_get',
      description: 'Get a note by its id.',
      inputSchema: {
        type: 'object',
        properties: {
          note_id: { type: 'string', description: 'The id of the note to retrieve.' },
        },
        required: ['note_id'],
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  if (name === 'note_create') {
    const { title, body } = args;
    assertString(title, 'title');
    assertString(body, 'body');
    counter += 1;
    const id = `n${counter}`;
    notes.set(id, { id, title, body });
    return {
      content: [{ type: 'text', text: `Created note ${id} with title "${title}".` }],
    };
  }
  if (name === 'note_get') {
    const { note_id } = args;
    if (typeof note_id !== 'string' || note_id.length === 0) {
      throw new Error('note_id is required and must be a non-empty string');
    }
    const note = notes.get(note_id);
    if (!note) {
      throw new Error(`Note not found: ${note_id}`);
    }
    return {
      content: [{ type: 'text', text: `${note.title}\n\n${note.body}` }],
    };
  }
  throw new Error(`Unknown tool: ${name}`);
}
```

